using System.Collections.Generic;
using System.IO;
using UnityEngine;

namespace KarmaClimb
{
    /// <summary>
    /// Loads the Eclipse 9-16 medal art embedded in the assembly (generated by tools/generate_medals.py).
    ///
    /// Each level has two states, like the Karma icons: Active once earned, Inactive until then. The
    /// Active sprite doubles as the difficulty icon shown in character select and the run HUD.
    /// </summary>
    internal static class KarmaClimbMedalArt
    {
        private static readonly Dictionary<string, Sprite> Cache = new Dictionary<string, Sprite>();

        internal static Sprite Active(int eclipseLevel) => Load($"texKarmaClimbMedal{eclipseLevel}Active");

        internal static Sprite Inactive(int eclipseLevel) => Load($"texKarmaClimbMedal{eclipseLevel}Inactive");

        private static Sprite Load(string name)
        {
            if (Cache.TryGetValue(name, out Sprite cached))
            {
                return cached;
            }

            Sprite sprite = null;
            string resource = $"KarmaClimb.Medals.{name}.png";

            using (Stream stream = typeof(KarmaClimbMedalArt).Assembly.GetManifestResourceStream(resource))
            {
                if (stream == null)
                {
                    Log.Error($"Missing embedded medal art {resource}.");
                }
                else
                {
                    using (MemoryStream buffer = new MemoryStream())
                    {
                        stream.CopyTo(buffer);

                        Texture2D texture = new Texture2D(2, 2, TextureFormat.RGBA32, mipChain: false)
                        {
                            name = name,
                            wrapMode = TextureWrapMode.Clamp,
                            filterMode = FilterMode.Bilinear,
                        };

                        if (texture.LoadImage(buffer.ToArray()))
                        {
                            sprite = Sprite.Create(
                                texture,
                                new Rect(0f, 0f, texture.width, texture.height),
                                new Vector2(0.5f, 0.5f));
                            sprite.name = name;
                        }
                        else
                        {
                            Log.Error($"Could not decode embedded medal art {resource}.");
                        }
                    }
                }
            }

            Cache[name] = sprite;
            return sprite;
        }
    }
}
